public with sharing class CaseSurveyJob implements Queueable {

    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        if (caseId == null) {
            return;
        }

        // Re-query so we have CaseNumber/ContactId and the current DB state at
        // execution time (the case could have been reopened or its contact removed
        // between enqueue and execution).
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (cases.isEmpty()) {
            return;
        }

        Case c = cases[0];
        if (!c.IsClosed || c.ContactId == null) {
            return;
        }

        Task t = new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert t;
    }
}
