public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one NPSP Data Import record per gift, preserving input order.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c      = g == null ? null : g.firstName;
            di.npsp__Contact1_Lastname__c       = g == null ? null : g.lastName;
            di.npsp__Contact1_Personal_Email__c = g == null ? null : g.email;
            di.npsp__Donation_Amount__c         = g == null ? null : g.amount;
            di.npsp__Donation_Date__c           = g == null ? null : g.giftDate;
            di.npsp__Donation_Donor__c          = 'Contact1';
            staged.add(di);
        }

        insert staged;

        // Capture ids in input order so we can re-query the processed rows afterwards.
        List<Id> stagedIds = new List<Id>();
        for (npsp__DataImport__c di : staged) {
            stagedIds.add(di.Id);
        }

        // 2. Process synchronously in this transaction using NPSP's BDI Apex API,
        //    with the org's Data Import settings. Ensure the contact matching rule
        //    is populated so NPSP matches existing donors (first name, last name,
        //    personal email) instead of creating duplicates.
        npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getOrgDefaults();

        if (String.isBlank(diSettings.npsp__Contact_Matching_Rule__c)) {
            diSettings.npsp__Contact_Matching_Rule__c =
                'npsp__Contact1_Firstname__c,npsp__Contact1_Lastname__c,npsp__Contact1_Personal_Email__c';
        }

        npsp.BDI_DataImport_API.processDataImportRecords(
            diSettings,
            staged,
            false // not a dry run - actually import
        );

        // 3. Re-query the processed records to read NPSP's results.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :stagedIds
            ]
        );

        // 4. Build one ImportResult per gift, in input order.
        for (Id stagedId : stagedIds) {
            npsp__DataImport__c di = processedById.get(stagedId);

            ImportResult r = new ImportResult();

            if (di == null) {
                r.success = false;
                r.errorMessage = 'Data Import record could not be retrieved after processing.';
                results.add(r);
                continue;
            }

            Boolean imported = di.npsp__Status__c == 'Imported';
            r.success = imported;
            r.contactId = di.npsp__Contact1Imported__c;
            r.opportunityId = di.npsp__DonationImported__c;

            if (!imported) {
                r.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                    ? di.npsp__FailureInformation__c
                    : 'NPSP did not import this gift (status: ' + di.npsp__Status__c + ').';
            }

            results.add(r);
        }

        return results;
    }
}
