/**
 * Service for importing family links as NPSP Relationships.
 *
 * NPSP's Relationship trigger (npe4) automatically creates the reciprocal
 * relationship record when a relationship is inserted, deriving the reciprocal
 * type from the Relationship Lookup settings (Male: Son, Female: Daughter,
 * Neutral: Child for the "Parent" lookup). Therefore we only insert the
 * child -> parent "Parent" record and let NPSP build the parent -> child side.
 */
public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input does nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all contacts involved so we can find any existing relationships
        // between the pairs in either direction with a single query.
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // Build a set of existing pairs (both directions) as "A|B" keys so we can
        // skip any pair that already has a relationship in either direction.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
            WITH USER_MODE
        ]) {
            existingPairKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            existingPairKeys.add(pairKey(rel.npe4__RelatedContact__c, rel.npe4__Contact__c));
        }

        // Guard against duplicate input pairs within this same call.
        Set<String> processedPairKeys = new Set<String>();

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String key = pairKey(childId, parentId);
            String reverseKey = pairKey(parentId, childId);

            // Skip if any relationship already exists in either direction,
            // or if we've already queued this pair in this run.
            if (existingPairKeys.contains(key)
                || existingPairKeys.contains(reverseKey)
                || processedPairKeys.contains(key)
                || processedPairKeys.contains(reverseKey)) {
                continue;
            }

            // Viewing the CHILD's relationships should show the PARENT as "Parent",
            // so the child is npe4__Contact__c and the parent is the related contact.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));

            processedPairKeys.add(key);
            processedPairKeys.add(reverseKey);
        }

        if (!toInsert.isEmpty()) {
            // Single DML. NPSP's trigger creates the reciprocal (Son/Daughter/Child).
            insert toInsert;
        }
    }

    private static String pairKey(Id a, Id b) {
        return String.valueOf(a) + '|' + String.valueOf(b);
    }
}
