public with sharing class RecordAccessService {

    // UserRecordAccess allows filtering on at most 200 RecordId values per query.
    private static final Integer MAX_IDS_PER_QUERY = 200;

    /**
     * Returns the subset of recordIds the running user can edit, as reported by
     * UserRecordAccess.HasEditAccess. This honours object permissions, ownership,
     * sharing, role hierarchy and View All/Modify All.
     *
     * A null or empty input returns an empty (non-null) set.
     * Safe for up to 2,000 IDs across multiple object types; uses at most
     * ceil(2000/200) = 10 SOQL queries for that volume.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Work from a de-duplicated, ordered list so we can chunk deterministically.
        List<Id> ids = new List<Id>(recordIds);

        for (Integer start = 0; start < ids.size(); start += MAX_IDS_PER_QUERY) {
            Integer stop = Math.min(start + MAX_IDS_PER_QUERY, ids.size());

            Set<Id> chunk = new Set<Id>();
            for (Integer i = start; i < stop; i++) {
                chunk.add(ids[i]);
            }

            for (UserRecordAccess access : [
                    SELECT RecordId, HasEditAccess
                    FROM UserRecordAccess
                    WHERE UserId = :UserInfo.getUserId()
                      AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
