```apex
public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        DescribeSObjectResult objDescribe = FB_Employee__c.sObjectType.getDescribe();

        // If the running user cannot read the object at all, return an empty list.
        if (!objDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Map<String, SObjectField> fieldMap = objDescribe.fields.getMap();

        // Always-queryable base fields.
        List<String> fieldsToQuery = new List<String>{ 'Id', 'Name' };

        // Only include the custom fields the running user can read, so the query
        // itself does not fail for fields the user lacks access to.
        for (String fieldName : new List<String>{
                'Department__c', 'Salary__c', 'Personal_Email__c' }) {
            SObjectField token = fieldMap.get(fieldName);
            if (token != null && token.getDescribe().isAccessible()) {
                fieldsToQuery.add(fieldName);
            }
        }

        // Query runs "with sharing" so only records visible through sharing are returned.
        String soql =
            'SELECT ' + String.join(fieldsToQuery, ', ') +
            ' FROM FB_Employee__c ORDER BY Name ASC';

        List<FB_Employee__c> records = Database.query(soql);

        // Defensively strip any remaining inaccessible fields without throwing.
        SObjectAccessDecision decision =
            Security.stripInaccessible(AccessType.READABLE, records);

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
