public with sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforce((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldMap = new Map<Id, Contact>();
        for (Contact oldCon : (List<Contact>) triggerOld) {
            oldMap.put(oldCon.Id, oldCon);
        }
        enforce((List<Contact>) triggerNew, oldMap);
    }

    private void enforce(List<Contact> newContacts, Map<Id, Contact> oldMap) {
        // Determine which contacts need checking (relevant = has account + email,
        // and on update only when Email or AccountId changed).
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact con : newContacts) {
            if (con.AccountId == null || String.isBlank(con.Email)) {
                continue;
            }
            if (oldMap != null) {
                Contact oldCon = oldMap.get(con.Id);
                if (oldCon != null
                    && con.AccountId == oldCon.AccountId
                    && normalize(con.Email) == normalize(oldCon.Email)) {
                    continue;
                }
            }
            toCheck.add(con);
            accountIds.add(con.AccountId);
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // Build set of existing account+email keys from the database (single query).
        Set<String> existingKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ]) {
            if (oldMap != null && oldMap.containsKey(existing.Id)) {
                // Skip records that are part of this same update batch; they are
                // evaluated via the in-memory list to avoid self conflicts.
                continue;
            }
            existingKeys.add(key(existing.AccountId, existing.Email));
        }

        // Track keys seen within this save so the first wins, later ones are rejected.
        Set<String> seenInBatch = new Set<String>();

        for (Contact con : toCheck) {
            String k = key(con.AccountId, con.Email);
            if (existingKeys.contains(k) || seenInBatch.contains(k)) {
                con.addError(ERROR_MESSAGE);
            } else {
                seenInBatch.add(k);
            }
        }
    }

    private String key(Id accountId, String email) {
        return String.valueOf(accountId) + '::' + normalize(email);
    }

    private String normalize(String email) {
        return email == null ? '' : email.trim().toLowerCase();
    }
}
